                hookSpecificOutput = @{
                    hookEventName     = $eventName
                    additionalContext = $Context
                }
            } | ConvertTo-Json -Compress -Depth 5
        }
        'Cursor' {
            @{ additional_context = $Context } | ConvertTo-Json -Compress
        }
        default {
            Write-Output $Context
        }
    }
}

